window.TADABBUR_ANAM = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة الأنعام (٦)، سورةٌ مكّيّةٌ في التوحيد وإبطالِ الشرك. كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، والنصُّ القرآنيُّ يُؤخذ من المورفولوجيا وقتَ العرض."},"n":6,"name":"الأنعام","total_ayahs":165,"audio":[],"passages":[{"title":"الحمدُ للخالق، وإعراضُ المكذّبين","range":[1,10],"theme":"توحيدُ الخالقِ المدبِّر، وعنادُ من يعدل به غيرَه ويعرض عن آياته","verses":[{"n":1,"reflection":{"text":"«الحمد لله الذي خلق السماوات والأرض وجعل الظلمات والنور ثم الذين كفروا بربهم يعدلون» — افتُتحت السورةُ بحمد الله على خلقه السماواتِ والأرضَ وجعلِه الظلماتِ والنور؛ فمن انفرد بالخلق استحقّ الحمدَ والعبادة؛ ومع هذا فالكافرون يجعلون له عِدلًا وشريكًا يعبدونه، وهذا غايةُ الظلم والعناد. فمن خلق كلَّ شيءٍ لا يُسوَّى به شيء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الخالقِ بالحمد والعبادة."},"action":{"text":"احمد الله على خلقه ونعمه، ولا تجعل له عِدلًا في عبادتك أو محبّتك."}},{"n":2,"reflection":{"text":"«هو الذي خلقكم من طين ثم قضى أجلا وأجل مسمى عنده ثم أنتم تمترون» — هو الذي خلق أباكم آدمَ من طين، وقدّر لكلٍّ أجلًا للموت، وأجلًا آخرَ مسمّى عنده للبعث؛ ثمّ أنتم — مع وضوح قدرته — تشكّون في البعث. فمن خلقكم أوّلًا قادرٌ على إعادتكم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ لمن قدر على الخلق."},"action":{"text":"اعمل لأجلك المسمّى، ولا تشكّ في البعث، فمن خلقك من طينٍ يعيدك."}},{"n":3,"reflection":{"text":"«وهو الله في السماوات وفي الأرض يعلم سركم وجهركم ويعلم ما تكسبون» — هو المعبودُ بحقٍّ في السماوات والأرض، المستحقُّ للعبادة فيهما؛ يعلم ما تُسرّون وما تُعلنون، ويعلم أعمالكم فيجازيكم؛ فعلمُه محيطٌ بكم. فراقبه في سرّك كما في علنك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ الله العالمِ بالسرّ والجهر."},"action":{"text":"استحضر علمَ الله بسرّك وعلنك، فأصلِح باطنك كما تُصلح ظاهرك."}},{"n":4,"reflection":{"text":"«وما تأتيهم من آية من آيات ربهم إلا كانوا عنها معرضين» — لا تأتي المكذّبين آيةٌ من آيات الله (كونيّةٌ أو قرآنيّة) إلا أعرضوا عنها ولم يتدبّروها؛ فالإعراضُ دأبُهم، لا نقصَ في الآيات. فالحجّةُ قائمةٌ، والعلّةُ في قلوبهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقّي الإعراضِ عن آيات الله والإقبالِ عليها."},"action":{"text":"لا تمرّ على آيات الله معرضًا، بل تدبّرها لتنتفع بها."}},{"n":5,"reflection":{"text":"«فقد كذبوا بالحق لما جاءهم فسوف يأتيهم أنباء ما كانوا به يستهزئون» — كذّبوا بالقرآن الحقّ حين جاءهم؛ فسوف تأتيهم عواقبُ استهزائهم وأخبارُ ما سخروا منه حين ينزل بهم العذاب؛ فالاستهزاءُ بالحقّ عاقبتُه وخيمة. فمن سخر بالحقّ لحقه سخريتُه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاستهزاءِ بالحقّ وعاقبتِه."},"action":{"text":"عظّم الحقَّ ولا تستهزئ به، فعاقبةُ الساخرِ أن يحيق به ما سخر منه."}},{"n":6,"reflection":{"text":"«ألم يروا كم أهلكنا من قبلهم من قرن مكناهم في الأرض ما لم نمكن لكم وأرسلنا السماء عليهم مدرارا وجعلنا الأنهار تجري من تحتهم فأهلكناهم بذنوبهم وأنشأنا من بعدهم قرنا آخرين» — ألم يعتبروا بمن أهلكنا قبلهم من أممٍ كانوا أقوى منهم تمكينًا وأوسعَ رزقًا (مطرًا وأنهارًا)، فأهلكهم الله بذنوبهم وأنشأ غيرهم؟ فالقوّةُ والنعمةُ لا تمنع عقوبةَ المصرّ. فاعتبروا بمصارع الأمم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعواقبِ الأمم المكذّبة."},"action":{"text":"تأمّل مصارعَ الأمم الظالمة، واعلم أنّ الذنوبَ تُهلك مهما كثُرت النعم."}},{"n":7,"reflection":{"text":"«ولو نزلنا عليك كتابا في قرطاس فلمسوه بأيديهم لقال الذين كفروا إن هذا إلا سحر مبين» — لو أنزلنا عليك كتابًا مكتوبًا في ورقٍ يرونه ويلمسونه لقال المعاندون: ما هذا إلا سحرٌ ظاهر؛ فعنادُهم لا تنفع معه الآيات؛ لأنّ المشكلةَ في إرادتهم لا في البيّنة. فالمعاندُ لا يُقنعه دليل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ العنادَ لا يُشفى بكثرة الأدلّة."},"action":{"text":"لا تُتعِب نفسك مع معاندٍ لا يريد الحقّ، فبيّنتُه لا تنقصه بل إرادتُه."}},{"n":8,"reflection":{"text":"«وقالوا لولا أنزل عليه ملك ولو أنزلنا ملكا لقضي الأمر ثم لا ينظرون» — اقترحوا أن يُنزَّل معه ملكٌ يُرى؛ ولو أنزلنا ملكًا على صورته الحقيقيّة ثمّ لم يؤمنوا لعُجّل لهم العذابُ ولم يُمهَلوا؛ فاقتراحُهم لو أُجيب لكان هلاكهم. فرحمةُ الله في إمهالهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لحكمة الله وتركُ اقتراحِ الآيات."},"action":{"text":"لا تقترح على الله آياتٍ، فتدبيرُه رحمةٌ، وإجابةُ اقتراحك قد تكون هلاكك."}},{"n":9,"reflection":{"text":"«ولو جعلناه ملكا لجعلناه رجلا وللبسنا عليهم ما يلبسون» — لو جعلنا الرسولَ ملكًا لجعلناه في صورة رجلٍ ليطيقوا رؤيته والأخذَ عنه، فيعود عليهم اللبسُ الذي فرّوا منه؛ فإرسالُ الرسول بشرًا من جنسهم رحمةٌ وحكمة. فبعثةُ البشرِ رحمةٌ لا نقص.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ حكمةِ بعثةِ الرسول من جنس البشر."},"action":{"text":"اشكر أن جعل رسولك بشرًا تفهم عنه وتتأسّى به، فذاك رحمةٌ وحكمة."}},{"n":10,"reflection":{"text":"«ولقد استهزئ برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزئون» — تسليةٌ للنبي ﷺ: قد استُهزئ برسلٍ قبلك، فأحاط بالساخرين العذابُ الذي استعجلوه واستهزؤوا به؛ فسنّةُ الله في الساخرين واحدة؛ فاصبر كما صبروا. فعاقبةُ الاستهزاءِ بالرسل الهلاك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الاستهزاء اقتداءً بالرسل."},"action":{"text":"اصبر على من يستهزئ بدينك، فعاقبةُ الساخرين حاقت بهم كما حاقت بمن قبلهم."}}]},{"title":"لله ما في الكون، وكتب على نفسه الرحمة","range":[11,18],"theme":"الاعتبارُ بعواقب المكذّبين، وأنّ الملكَ لله كتب الرحمةَ على نفسه، وهو القاهرُ النافعُ الضارّ","verses":[{"n":11,"reflection":{"text":"«قل سيروا في الأرض ثم انظروا كيف كان عاقبة المكذبين» — قل لهم: سيروا في الأرض متأمّلين آثارَ الأمم المكذّبة كيف كان مصيرُهم، لتعتبروا؛ فالسيرُ للعبرة لا للهو. فالتاريخُ موعظةٌ لمن تأمّل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بمصارعِ المكذّبين عند التأمّل."},"action":{"text":"تأمّل عواقبَ المكذّبين في التاريخ والآثار لتزداد يقينًا بسنّة الله."}},{"n":12,"reflection":{"text":"«قل لمن ما في السماوات والأرض قل لله كتب على نفسه الرحمة ليجمعنكم إلى يوم القيامة لا ريب فيه الذين خسروا أنفسهم فهم لا يؤمنون» — قل: لمن ملكُ الكون؟ ثمّ أجِب: لله؛ وقد كتب على نفسه الرحمةَ تفضّلًا (وفي الحديث: إنّ رحمتي سبقت غضبي)؛ وليجمعنّكم ليوم القيامة الذي لا شكّ فيه؛ والخاسرون هم الذين لا يؤمنون. فرحمتُه سبقت، والبعثُ حقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الرحمن"],"heart_state":{"text":"الرجاءُ في رحمةِ الله التي كتبها على نفسه."},"action":{"text":"ارجُ رحمةَ الله التي سبقت غضبه، واعمل ليوم الجمع الذي لا ريب فيه."}},{"n":13,"reflection":{"text":"«وله ما سكن في الليل والنهار وهو السميع العليم» — لله كلُّ ما استقرّ في الليل والنهار من المخلوقات، فالكلُّ ملكُه وتحت تدبيره؛ وهو السميعُ لأصواتهم، العليمُ بأحوالهم؛ فلا يخفى عليه شيء. فمن هذا ملكُه وعلمُه هو المعبودُ وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":["السميع","العليم"],"heart_state":{"text":"استحضارُ سمعِ الله وعلمِه بكلّ ساكنٍ ومتحرّك."},"action":{"text":"اعلم أنّ كلَّ ما في الكون ملكُ الله، يسمع ويعلم، فاعبده وحده."}},{"n":14,"reflection":{"text":"«قل أغير الله أتخذ وليا فاطر السماوات والأرض وهو يطعم ولا يطعم قل إني أمرت أن أكون أول من أسلم ولا تكونن من المشركين» — قل منكرًا: أأتّخذ غيرَ الله وليًّا وهو مبدع السماوات والأرض، يرزق ولا يُرزق، غنيٌّ عن خلقه؟ وأُمرتُ أن أكون أوّلَ المسلمين من هذه الأمّة، ونُهيتُ عن الشرك. فالوليُّ الحقُّ هو الخالقُ الرازق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّخاذُ الله وحده وليًّا لأنّه الخالقُ الرازق."},"action":{"text":"اتّخذ الله وحده وليًّا، فهو الغنيُّ الذي يرزق ولا يُرزق، ولا تشرك به."}},{"n":15,"reflection":{"text":"«قل إني أخاف إن عصيت ربي عذاب يوم عظيم» — قل: إنّي مع مكانتي أخاف إن عصيتُ ربّي عذابَ يومٍ عظيم؛ فإذا كان النبيُّ يخاف فغيرُه أولى؛ والخوفُ من عذاب الله يحمل على الطاعة. فالتقوى خوفٌ يثمر عملًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"خوفُ عذابِ الله الباعثُ على الطاعة."},"action":{"text":"اجعل خوفَ عذاب الله حاجزًا لك عن معصيته، فحتى النبيُّ كان يخافه."}},{"n":16,"reflection":{"text":"«من يصرف عنه يومئذ فقد رحمه وذلك الفوز المبين» — من يُصرَف عنه عذابُ ذلك اليوم العظيم فقد رحمه الله؛ وذلك هو الفوز الظاهر البيّن؛ فالنجاةُ من النار غايةُ الفوز. فأعظمُ الرحمةِ النجاةُ يومَ القيامة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ النجاةِ من عذاب ذلك اليوم رحمةً وفوزًا."},"action":{"text":"اعمل لتُصرف عنك النارُ يومَ القيامة، فتلك رحمةٌ وفوزٌ مبين."}},{"n":17,"reflection":{"text":"«وإن يمسسك الله بضر فلا كاشف له إلا هو وإن يمسسك بخير فهو على كل شيء قدير» — إن أصابك الله بضرٍّ فلا يقدر على رفعه أحدٌ سواه، وإن أصابك بخيرٍ فلا رادّ لفضله، وهو على كلّ شيء قدير؛ فالنفعُ والضرُّ بيده وحده؛ فلا تعلّق قلبك بسواه. فمن بيده كلُّ شيءٍ يُرجى ويُخاف.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["القدير"],"heart_state":{"text":"تعليقُ القلبِ بالله وحده في الضرّ والنفع."},"action":{"text":"علّق رجاءك وخوفك بالله وحده، فلا كاشفَ لضرّك ولا مانعَ لخيره سواه."}},{"n":18,"reflection":{"text":"«وهو القاهر فوق عباده وهو الحكيم الخبير» — هو الغالبُ القاهرُ فوق عباده، خضع له كلُّ شيء وذلّ لعظمته؛ وهو الحكيمُ في تدبيره، الخبيرُ بأحوال خلقه؛ فقهرُه مقرونٌ بحكمةٍ وعلم. فاخضع لمن قهر كلَّ شيءٍ بحكمة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["القاهر","الحكيم","الخبير"],"heart_state":{"text":"الخضوعُ لله القاهرِ الحكيمِ الخبير."},"action":{"text":"اخضع لله القاهرِ فوق عباده، واطمئن أنّ قهره مقرونٌ بحكمةٍ وخبرة."}}]},{"title":"شهادةُ الله بالتوحيد، وأظلمُ الناس","range":[19,25],"theme":"الله أكبرُ شهادةً على التوحيد، وأظلمُ الناسِ مفترٍ أو مكذّب، وحالُ من طُبع على قلبه","verses":[{"n":19,"reflection":{"text":"«قل أي شيء أكبر شهادة قل الله شهيد بيني وبينكم وأوحي إلي هذا القرآن لأنذركم به ومن بلغ أئنكم لتشهدون أن مع الله آلهة أخرى قل لا أشهد قل إنما هو إله واحد وإنني بريء مما تشركون» — قل: أعظمُ شهادةٍ شهادةُ الله، وهو شهيدٌ بيني وبينكم على صدقي؛ وأُوحي إليّ هذا القرآن لأنذركم به وأُنذر كلَّ من بلغه إلى قيام الساعة؛ ثمّ تبرّأ من شركهم: إنّما هو إلهٌ واحدٌ وأنا بريءٌ ممّا تشركون. فالقرآنُ نذيرٌ لكلّ من بلغه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتزازُ بالتوحيد والبراءةُ من الشرك."},"action":{"text":"أعلن توحيدك وابرأ من كلّ شرك، واعلم أنّ القرآن نذيرٌ لك ما بلغك."}},{"n":20,"reflection":{"text":"«الذين آتيناهم الكتاب يعرفونه كما يعرفون أبناءهم الذين خسروا أنفسهم فهم لا يؤمنون» — علماءُ أهل الكتاب يعرفون صدقَ محمدٍ ونبوّتَه معرفةً يقينيّةً كمعرفتهم أبناءهم (لما عندهم من صفته)؛ لكنّ الذين خسروا أنفسهم بالعناد لا يؤمنون. فالمعرفةُ وحدها لا تنفع بلا إذعان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أن يقود العلمُ إلى الإذعان لا العناد."},"action":{"text":"لا يكفي أن تعرف الحقّ، بل أذعِن له واعمل، فالمعرفةُ بلا إيمانٍ خسارة."}},{"n":21,"reflection":{"text":"«ومن أظلم ممن افترى على الله كذبا أو كذب بآياته إنه لا يفلح الظالمون» — لا أحدَ أظلمُ ممّن اختلق على الله كذبًا (كنسبة الشريك والولد) أو كذّب بآياته الحقّ؛ إنّه لا يفوز الظالمون بمطلوبهم؛ فجمعوا بين الافتراء والتكذيب. فالكذبُ على الله والتكذيبُ به قمّةُ الظلم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقّي الكذبِ على الله والتكذيبِ بآياته."},"action":{"text":"لا تقُل على الله ما لا تعلم، ولا تكذّب بحقٍّ ثبت، فذاك أظلمُ الظلم."}},{"n":22,"reflection":{"text":"«ويوم نحشرهم جميعا ثم نقول للذين أشركوا أين شركاؤكم الذين كنتم تزعمون» — ويومَ نجمع الخلقَ جميعًا نقول توبيخًا للمشركين: أين آلهتُكم الذين زعمتم أنّهم شركاء وشفعاء؟ فلا يجدون منهم نصيرًا؛ ينكشف بطلانُ ما عبدوا. فالشركاءُ المزعومون يتخلّون عن عابديهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ ما عُبد دون الله يخذل يوم القيامة."},"action":{"text":"لا تعلّق رجاءك بغير الله، فكلُّ معبودٍ سواه يتخلّى عن صاحبه يومَ الحشر."}},{"n":23,"reflection":{"text":"«ثم لم تكن فتنتهم إلا أن قالوا والله ربنا ما كنا مشركين» — ثمّ لا يكون جوابُهم واعتذارُهم إلا أن يحلفوا كذبًا: والله ربّنا ما كنّا مشركين؛ يجحدون شركهم فرارًا من العقوبة، فيكذبون في موقفٍ لا ينفع فيه الكذب. فمن اعتاد الكذبَ كذب حتى على الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصدقُ مع الله، فالكذبُ لا ينفع يومَ القيامة."},"action":{"text":"تعوّد الصدقَ في الدنيا، فمن كذب فيها كذب يومَ القيامة حيث لا ينفع."}},{"n":24,"reflection":{"text":"«انظر كيف كذبوا على أنفسهم وضل عنهم ما كانوا يفترون» — انظر كيف كذبوا على أنفسهم بجحد شركهم، وغاب عنهم ما كانوا يختلقونه من الشركاء والشفعاء فلم ينفعهم؛ فافتضح كذبُهم وبطل افتراؤهم. فالباطلُ يزول وينكشف يومَ الحقيقة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ الباطلَ يزول وينكشف."},"action":{"text":"ابنِ أمرك على الحقّ لا على الافتراء، فالباطلُ يضلّ عن صاحبه ويفتضح."}},{"n":25,"reflection":{"text":"«ومنهم من يستمع إليك وجعلنا على قلوبهم أكنة أن يفقهوه وفي آذانهم وقرا وإن يروا كل آية لا يؤمنوا بها حتى إذا جاءوك يجادلونك يقول الذين كفروا إن هذا إلا أساطير الأولين» — منهم من يستمع لك بأذنه لا بقلبه؛ فبإعراضهم جُعل على قلوبهم أغطيةٌ تمنع الفهم وفي آذانهم صممٌ عن القبول؛ فلو رأوا كلَّ آيةٍ لم يؤمنوا، ويجادلونك زاعمين أنّ القرآن أباطيرُ الأقدمين؛ فالاستماعُ بلا قصدِ اهتداءٍ لا ينفع. فالسماعُ النافعُ ما واطأه القلب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستماعُ للقرآن بقلبٍ مقبلٍ لا معرض."},"action":{"text":"استمع للقرآن بقلبٍ يريد الهدى، فالسماعُ بلا إقبالِ قلبٍ لا يُفقِه."}}]},{"title":"حسرةُ المكذّبين عند النار، وخسّةُ الدنيا","range":[26,32],"theme":"تمنّي الكافرين الرجوعَ، وندمُ من فرّط، وأنّ الآخرةَ خيرٌ للمتّقين","verses":[{"n":26,"reflection":{"text":"«وهم ينهون عنه وينأون عنه وإن يهلكون إلا أنفسهم وما يشعرون» — ينهَون الناسَ عن اتّباع النبيّ ويبتعدون هم عنه؛ فيجمعون بين الضلال والإضلال؛ وما يُهلكون بذلك إلا أنفسهم وهم لا يشعرون بعاقبة صنيعهم. فالصادُّ عن الحقّ يهلك نفسه أوّلًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقّي الصدِّ عن الحقّ والبعدِ عنه."},"action":{"text":"لا تصدّ أحدًا عن الحقّ ولا تبتعد عنه، فالصادُّ يهلك نفسه."}},{"n":27,"reflection":{"text":"«ولو ترى إذ وقفوا على النار فقالوا يا ليتنا نرد ولا نكذب بآيات ربنا ونكون من المؤمنين» — لو ترى حالهم إذ عُرضوا على النار فتمنّوا الرجوعَ ليؤمنوا ولا يكذّبوا؛ لرأيت أمرًا عظيمًا؛ لكنّه تمنٍّ بعد فوات الأوان. فبادر بالإيمان قبل أن تتمنّى الرجوعَ ولا رجوع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالإيمان قبل أن يُتمنّى الرجوع."},"action":{"text":"آمن واعمل الآن، فأهلُ النار يتمنّون الرجوعَ ولا يُجابون."}},{"n":28,"reflection":{"text":"«بل بدا لهم ما كانوا يخفون من قبل ولو ردوا لعادوا لما نهوا عنه وإنهم لكاذبون» — بل ظهر لهم ما كانوا يُخفون من كفرهم ونفاقهم؛ ولو رُدّوا إلى الدنيا لعادوا لما نُهوا عنه، فتمنّيهم غيرُ صادق، وإنّهم لكاذبون في وعدهم. فالطبعُ لا يتغيّر بمجرّد رؤية العاقبة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"صدقُ العزمِ على التوبة لا مجرّدُ التمنّي."},"action":{"text":"اصدق في توبتك وعزمك الآن، فالتمنّي بلا صدقٍ لا يغيّر النفس."}},{"n":29,"reflection":{"text":"«وقالوا إن هي إلا حياتنا الدنيا وما نحن بمبعوثين» — كانوا يقولون منكرين البعث: ما هي إلا هذه الحياة الدنيا نموت فيها ولا نُبعث؛ فأنكروا الآخرة فجرّهم ذلك إلى الكفر والفجور. فإنكارُ البعث أصلُ الفجور.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ الرادعُ عن الفجور."},"action":{"text":"أيقِن بالبعث والحساب، فإنكارُه بابُ الغفلة والفجور."}},{"n":30,"reflection":{"text":"«ولو ترى إذ وقفوا على ربهم قال أليس هذا بالحق قالوا بلى وربنا قال فذوقوا العذاب بما كنتم تكفرون» — لو تراهم حين يُوقَفون بين يدي ربّهم فيقول: أليس هذا البعثُ حقًّا؟ فيقرّون: بلى وربّنا؛ فيقال: ذوقوا العذابَ بكفركم؛ فأقرّوا حين لا ينفع الإقرار. فالحقُّ يُقَرُّ به يومًا ولو بعد جحود.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقرارُ بالحقّ الآن حيث ينفع الإقرار."},"action":{"text":"أقرَّ بالحقّ واعمل به اليوم، فالمكذّبون يُقرّون به يومَ لا ينفعهم."}},{"n":31,"reflection":{"text":"«قد خسر الذين كذبوا بلقاء الله حتى إذا جاءتهم الساعة بغتة قالوا يا حسرتنا على ما فرطنا فيها وهم يحملون أوزارهم على ظهورهم ألا ساء ما يزرون» — خسر المكذّبون بلقاء الله والبعث، حتى إذا فاجأتهم الساعةُ تحسّروا على تفريطهم، وهم يحملون آثامهم أثقالًا على ظهورهم؛ بئس ما يحملون. فالتفريطُ في العمل حسرةٌ يومَ القيامة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التفريطِ الذي يورث الحسرة."},"action":{"text":"لا تفرّط في عملك للآخرة، فالمفرّطون يتحسّرون يومَ تُفاجئهم الساعة."}},{"n":32,"reflection":{"text":"«وما الحياة الدنيا إلا لعب ولهو وللدار الآخرة خير للذين يتقون أفلا تعقلون» — ليست الدنيا في جنب الآخرة إلا لعبًا يشغل ولهوًا يُلهي عن الحقّ؛ والدارُ الآخرةُ خيرٌ وأبقى للمتّقين؛ أفلا تعقلون فتؤثرون الباقيَ على الفاني؟ فالعاقلُ يعمل للباقية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إيثارُ الآخرةِ الباقيةِ على الدنيا اللاهية."},"action":{"text":"لا تجعل الدنيا أكبرَ همّك، فهي لعبٌ ولهو، والآخرةُ خيرٌ للمتّقين."}}]},{"title":"تسليةُ النبي، وأنّ المستجيبَ من يسمع","range":[33,36],"theme":"عزاءُ النبي عن جحود قومه، وصبرُ الرسل حتى النصر، وأنّ المنتفعَ من يُصغي بقلبه","verses":[{"n":33,"reflection":{"text":"«قد نعلم إنه ليحزنك الذي يقولون فإنهم لا يكذبونك ولكن الظالمين بآيات الله يجحدون» — نعلم أنّ تكذيبهم يحزنك يا محمد؛ لكنّهم في قرارة أنفسهم لا يكذّبونك — فهم يعرفون صدقك — وإنّما يجحدون آياتِ الله عنادًا وظلمًا؛ فالتكذيبُ لله لا لك في الحقيقة. فتكذيبُ الظالمين للحقّ جحودٌ لا شكّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسلّي بأنّ ردَّ الحقّ جحودٌ لا تكذيبٌ لك."},"action":{"text":"لا يحزنك ردُّ الناس للحقّ، فهم يجحدون آياتِ الله عنادًا لا لشكٍّ فيك."}},{"n":34,"reflection":{"text":"«ولقد كذبت رسل من قبلك فصبروا على ما كذبوا وأوذوا حتى أتاهم نصرنا ولا مبدل لكلمات الله ولقد جاءك من نبإ المرسلين» — قد كُذّب رسلٌ قبلك فصبروا على التكذيب والأذى حتى جاءهم نصرُ الله؛ ولا مغيّرَ لوعده بنصر رسله؛ وقد جاءك من أخبارهم ما يثبّتك؛ فاصبر كما صبروا يأتك النصر. فالصبرُ سبيلُ النصر، ووعدُ الله لا يتبدّل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الأذى ثقةً بوعدِ الله بالنصر."},"action":{"text":"اصبر على أذى الحقّ كما صبر الرسل، فوعدُ الله بالنصر لا يتبدّل."}},{"n":35,"reflection":{"text":"«وإن كان كبر عليك إعراضهم فإن استطعت أن تبتغي نفقا في الأرض أو سلما في السماء فتأتيهم بآية ولو شاء الله لجمعهم على الهدى فلا تكونن من الجاهلين» — إن شقّ عليك إعراضُهم فلن تُكرههم على الإيمان ولو استطعت أن تنفذ في الأرض أو تصعد إلى السماء لتأتيهم بآية؛ ولو شاء الله لجمعهم على الهدى، لكنّه ابتلاء؛ فسلِّم لحكمته ولا تحمل همًّا لا يُطاق. فالهدايةُ بيد الله لا بيدك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لحكمة الله في الهداية وطرحُ الحرص المفرط."},"action":{"text":"بلّغ ولا تحمل همَّ من أعرض فوق طاقتك، فالهدايةُ بيد الله وحده."}},{"n":36,"reflection":{"text":"«إنما يستجيب الذين يسمعون والموتى يبعثهم الله ثم إليه يرجعون» — إنّما ينتفع بدعوتك ويستجيب أحياءُ القلوب الذين يسمعون سماعَ قبولٍ؛ وأمّا موتى القلوب (كالكفار) فهم كالأموات لا يسمعون، والله يبعث الأمواتَ يومَ القيامة ثمّ إليه المرجع فيجازيهم. فالمنتفعُ من كان حيَّ القلب مصغيًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ حياةِ القلبِ لسماعِ الحقّ والانتفاعِ به."},"action":{"text":"أحيِ قلبك بالإقبال على الحقّ، فالمنتفعُ من يسمع بقلبٍ حيٍّ لا ميّت."}}]},{"title":"الدوابُّ أممٌ أمثالكم، وكشفُ الضرّ بيده","range":[37,41],"theme":"شمولُ علمِ الله بكلّ خلقه، وأنّ المكذّبين صمٌّ بكم، وأنّ الملتجأَ عند الشدّة هو الله وحده","verses":[{"n":37,"reflection":{"text":"«وقالوا لولا نزل عليه آية من ربه قل إن الله قادر على أن ينزل آية ولكن أكثرهم لا يعلمون» — اقترحوا آيةً حسّيّةً من ربّه (كناقة صالح)؛ قل: الله قادرٌ على إنزالها، لكن حكمتَه اقتضت غيرَ ذلك، ولو أُنزلت فكذّبوا لعُوجِّلوا بالهلاك؛ وأكثرهم لا يعلمون حكمةَ الله. فمنعُ ما اقترحوه رحمةٌ وحكمة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لحكمة الله في تدبيره وآياته."},"action":{"text":"لا تقترح على الله، فقدرتُه لا تُحدّ، وحكمتُه في المنع كما في العطاء."}},{"n":38,"reflection":{"text":"«وما من دابة في الأرض ولا طائر يطير بجناحيه إلا أمم أمثالكم ما فرطنا في الكتاب من شيء ثم إلى ربهم يحشرون» — كلُّ دابّةٍ في الأرض وكلُّ طائرٍ أممٌ أمثالكم في الخلق والرزق والتدبير، يعلمها الله ويرزقها؛ وما تركنا في اللوح المحفوظ (أو القرآن) شيئًا من علم مصالحهم؛ ثمّ تُحشر كلُّها إلى ربّها. فعلمُ الله وتدبيرُه يسع كلَّ مخلوق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ إحاطةِ الله برزقِ كلِّ دابّة وتدبيرِها."},"action":{"text":"تأمّل عنايةَ الله بكلّ دابّةٍ وطائر، واطمئن أنّ رزقك عليه ومصيرك إليه."}},{"n":39,"reflection":{"text":"«والذين كذبوا بآياتنا صم وبكم في الظلمات من يشإ الله يضلله ومن يشأ يجعله على صراط مستقيم» — المكذّبون بآياتنا كالصمّ لا يسمعون الحقَّ، والبكم لا ينطقون به، غارقون في ظلمات الجهل والكفر؛ ومشيئةُ الله نافذة: من يشأ يضلّه بعدله، ومن يشأ يهديه بفضله؛ فاطلب الهدايةَ من مالكها. فالهدايةُ والإضلالُ بيد الله وفق حكمته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الهدايةِ من الله واجتنابُ أسبابِ الإضلال."},"action":{"text":"اسأل الله الهدايةَ إلى صراطه المستقيم، واجتنب ما يُصمّ القلبَ عن الحق."}},{"n":40,"reflection":{"text":"«قل أرأيتكم إن أتاكم عذاب الله أو أتتكم الساعة أغير الله تدعون إن كنتم صادقين» — قل لهم: أخبروني، إن نزل بكم عذابُ الله أو قامت الساعةُ، أتدعون غيرَ الله لكشفه إن كنتم صادقين في اتّخاذ الشركاء؟ لا، بل تلجؤون إليه وحده؛ فلِمَ تعبدون سواه في الرخاء؟ ففطرةُ اللجوء لله تنكشف عند الشدّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اللجوءُ إلى الله وحده في الرخاء كما في الشدّة."},"action":{"text":"الجأ إلى الله وحده دائمًا، فأنت لا تدعو سواه حين ينزل بك الكرب."}},{"n":41,"reflection":{"text":"«بل إياه تدعون فيكشف ما تدعون إليه إن شاء وتنسون ما تشركون» — بل تدعون الله وحده عند الشدّة فيكشف ضرّكم إن شاء بحكمته، وتنسون آلهتكم التي كنتم تشركونها؛ فدلّ اضطرارُكم إليه على أنّه المعبودُ الحقّ. فالشدائدُ تُرجع القلبَ إلى فطرته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ الدعاءِ لله المُجيبِ عند الاضطرار."},"action":{"text":"أخلص دعاءك لله الذي يكشف ضرّك، ولا تشرك به من لا يملك لك شيئًا."}}]},{"title":"سنّةُ البأساء والاستدراج، وقطعُ دابرِ الظالمين","range":[42,45],"theme":"الابتلاءُ للتضرّع، وقسوةُ القلب تمنعه، والاستدراجُ بالنعم ثمّ الأخذُ بغتة","verses":[{"n":42,"reflection":{"text":"«ولقد أرسلنا إلى أمم من قبلك فأخذناهم بالبأساء والضراء لعلهم يتضرعون» — أرسلنا رسلًا إلى أممٍ قبلك فكذّبوا، فابتليناهم بالفقر والشدّة والمرض لعلّهم يخضعون ويتضرّعون إلى الله فيرجعوا؛ فالبلاءُ رسالةٌ تدعو للرجوع. فالشدائدُ تُساق ليتذكّر الغافل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التضرّعُ إلى الله عند البلاء والرجوعُ إليه."},"action":{"text":"إذا أصابك بلاءٌ فتضرّع إلى الله وارجع إليه، فالبلاءُ يدعوك إليه."}},{"n":43,"reflection":{"text":"«فلولا إذ جاءهم بأسنا تضرعوا ولكن قست قلوبهم وزين لهم الشيطان ما كانوا يعملون» — فهلّا تضرّعوا حين نزل بهم عذابنا؟ لكنّ قلوبهم قست فلم تلن، وزيّن لهم الشيطانُ كفرَهم ومعاصيهم فأصرّوا؛ فقسوةُ القلب تمنع الاتّعاظ. فالإصرارُ مع البلاء علامةُ قسوةِ القلب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من قسوةِ القلبِ التي تمنع التضرّع."},"action":{"text":"لن قلبك للحقّ عند البلاء، واحذر قسوةً تمنعك من الرجوع إلى الله."}},{"n":44,"reflection":{"text":"«فلما نسوا ما ذكروا به فتحنا عليهم أبواب كل شيء حتى إذا فرحوا بما أوتوا أخذناهم بغتة فإذا هم مبلسون» — فلمّا أعرضوا وتركوا ما ذُكّروا به، فتحنا عليهم أبوابَ الرزق والنعم استدراجًا لا كرامةً، حتى إذا فرحوا واغترّوا أخذناهم فجأةً بالعذاب فإذا هم آيسون متحيّرون؛ فالنعمةُ مع المعصية قد تكون استدراجًا. فاحذر أن تُفتح لك الأبوابُ وأنت مصرّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من استدراجِ النعمِ مع الإصرار على المعصية."},"action":{"text":"لا تغترّ بسعةِ الرزق مع المعصية، فقد تكون استدراجًا يعقبه أخذٌ بغتة."}},{"n":45,"reflection":{"text":"«فقطع دابر القوم الذين ظلموا والحمد لله رب العالمين» — فاستُؤصل آخرُ الظالمين حتى لم يبقَ منهم أحد؛ والحمدُ لله ربّ العالمين على هلاك الظالمين ونجاةِ المؤمنين، فهو حمدٌ على عدله كما يُحمد على فضله. فعاقبةُ الظلمِ الاستئصال، والحمدُ لله على عدله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"حمدُ الله على عدلِه في إهلاك الظالمين."},"action":{"text":"احمد الله على عدله كما تحمده على فضله، واعلم أنّ عاقبةَ الظلم البتر."}}]},{"title":"من يردّ سمعك وبصرك؟ ومهمّةُ الرسل","range":[46,51],"theme":"انفرادُ الله بالنعم والعقوبة، والرسلُ مبشّرون ومنذرون، وتواضعُ النبي وصدقُه","verses":[{"n":46,"reflection":{"text":"«قل أرأيتم إن أخذ الله سمعكم وأبصاركم وختم على قلوبكم من إله غير الله يأتيكم به انظر كيف نصرف الآيات ثم هم يصدفون» — قل: أخبروني، لو سلبكم الله سمعكم وأبصاركم وطبع على قلوبكم، أيّ إلهٍ غيره يردّها إليكم؟ لا أحد؛ انظر كيف نبيّن الآياتِ بأنواعها ثمّ هم يُعرضون؛ فالنعمُ منه وحده، فكيف يُعبد سواه؟ فمن يملك حواسّك هو المستحقُّ للعبادة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ السمعِ والبصرِ والقلبِ لواهبها."},"action":{"text":"اشكر الله على سمعك وبصرك وقلبك، واستعملها في طاعته، فهو واهبُها."}},{"n":47,"reflection":{"text":"«قل أرأيتكم إن أتاكم عذاب الله بغتة أو جهرة هل يهلك إلا القوم الظالمون» — قل: إن جاءكم عذابُ الله فجأةً أو معلنًا، هل يُهلَك بالعذاب إلا الظالمون المكذّبون؟ فالعقوبةُ عدلٌ تحلّ بأهل الظلم؛ فاحذروا الظلمَ الذي يجلبها. فالنجاةُ بترك الظلم والكفر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقّي الظلمِ الجالبِ للعذاب."},"action":{"text":"اجتنب الظلمَ والكفر، فالعذابُ لا يحلّ إلا بالظالمين."}},{"n":48,"reflection":{"text":"«وما نرسل المرسلين إلا مبشرين ومنذرين فمن آمن وأصلح فلا خوف عليهم ولا هم يحزنون» — ما أرسلنا الرسلَ إلا ليبشّروا المطيعين ويُنذروا العاصين؛ فمن آمن وأصلح عملَه فلا خوفٌ عليهم فيما يستقبلون ولا حزنٌ على ما فات؛ فأمنُ الآخرة للمؤمن المصلح. فالإيمانُ والإصلاحُ أمانٌ وطمأنينة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين الإيمانِ والإصلاحِ لنيلِ الأمن."},"action":{"text":"آمن وأصلح عملك، فبهما يأمن القلبُ فلا خوفٌ ولا حزن."}},{"n":49,"reflection":{"text":"«والذين كذبوا بآياتنا يمسهم العذاب بما كانوا يفسقون» — والذين كذّبوا بآيات الله يصيبهم العذابُ بسبب خروجهم عن طاعته وإصرارهم على الفسق؛ فالجزاءُ من جنس العمل. فالتكذيبُ والفسوقُ يجلبان العذاب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التكذيبِ والفسوقِ الجالبَين للعذاب."},"action":{"text":"صدّق بآيات الله والزم طاعته، فالتكذيبُ والفسقُ سببُ العذاب."}},{"n":50,"reflection":{"text":"«قل لا أقول لكم عندي خزائن الله ولا أعلم الغيب ولا أقول لكم إني ملك إن أتبع إلا ما يوحى إلي قل هل يستوي الأعمى والبصير أفلا تتفكرون» — قل متواضعًا: لا أدّعي ملكَ خزائن الله، ولا علمَ الغيب، ولا أنّي ملَك؛ إنّما أتّبع الوحيَ فأبلّغه؛ ثمّ قل: هل يستوي الأعمى (الكافر) والبصير (المؤمن)؟ أفلا تتفكّرون فتختاروا البصيرة؟ فصدقُ النبي في تواضعه وحصرِ دعواه في البلاغ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواضعُ وحصرُ الدعوى في اتّباعِ الوحي."},"action":{"text":"لا تدّعِ ما ليس لك، واتّبع الوحيَ، فالبصيرةُ في الإيمان لا في العمى."}},{"n":51,"reflection":{"text":"«وأنذر به الذين يخافون أن يحشروا إلى ربهم ليس لهم من دونه ولي ولا شفيع لعلهم يتقون» — أنذر بالقرآن الذين يخافون البعثَ والحشرَ إلى ربّهم، الذين يعلمون أنّه لا وليَّ لهم ولا شفيعَ سواه؛ فهؤلاء ينتفعون بالإنذار لعلّهم يتّقون؛ فالإنذارُ ينفع خائفَ القلب. فالمنتفعُ بالتذكير من يخاف لقاء الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ الحشرِ وأنّه لا وليَّ ولا شفيعَ سوى الله."},"action":{"text":"اعمل بخوف لقاء الله، فلا وليَّ لك ولا شفيعَ يومئذٍ إلا هو."}}]},{"title":"لا تطرد الضعفاء، ورحمةُ الله بالمؤمنين","range":[52,55],"theme":"تكريمُ الفقراء المخلصين، وأنّ الفتنةَ بالتفاوت اختبار، وسلامُ الله على المؤمنين","verses":[{"n":52,"reflection":{"text":"«ولا تطرد الذين يدعون ربهم بالغداة والعشي يريدون وجهه ما عليك من حسابهم من شيء وما من حسابك عليهم من شيء فتطردهم فتكون من الظالمين» — لا تُبعِد الفقراءَ المخلصين (كبلالٍ وصهيبٍ وعمّار) الذين يعبدون ربّهم صباحًا ومساءً مريدين وجهه، إرضاءً لكبراء المشركين؛ فلست محاسبًا على نيّاتهم ولا هم على نيّتك؛ فطردُهم ظلم. فلا تُقدّم وجيهًا كافرًا على فقيرٍ مؤمن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تكريمُ المؤمن الفقير وعدمُ ازدرائه."},"action":{"text":"أكرِم أهلَ الإيمان ولو كانوا فقراء، ولا تُقصِهم إرضاءً لوجيهٍ أو غنيّ."}},{"n":53,"reflection":{"text":"«وكذلك فتنا بعضهم ببعض ليقولوا أهؤلاء من الله عليهم من بيننا أليس الله بأعلم بالشاكرين» — وهكذا اختبرنا الناسَ بعضهم ببعض (الغنيَّ بالفقير، والشريفَ بالوضيع) حتى يقول المتكبّرون مستنكرين: أهؤلاء الضعفاءُ منّ الله عليهم بالإيمان دوننا؟ أليس الله أعلمَ بمن يشكر نعمته فيهديه؟ فالله يهدي من علم منه الشكرَ لا من زعم الشرف.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ كرامةَ الله لأهل الشكر لا للجاه."},"action":{"text":"لا تحتقر مؤمنًا لضعفه، فالله يهدي الشاكرين وإن ازدراهم المتكبّرون."}},{"n":54,"reflection":{"text":"«وإذا جاءك الذين يؤمنون بآياتنا فقل سلام عليكم كتب ربكم على نفسه الرحمة أنه من عمل منكم سوءا بجهالة ثم تاب من بعده وأصلح فأنه غفور رحيم» — إذا جاءك المؤمنون فابدأهم بالسلام وبشّرهم بسعة رحمة الله: من عمل منكم ذنبًا بجهالةٍ ثمّ تاب وأصلح فإنّ الله غفورٌ رحيم؛ فرحمتُه كتبها على نفسه لعباده التائبين. فبابُ الرحمة مفتوحٌ لمن تاب وأصلح.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغفور","الرحيم"],"heart_state":{"text":"الرجاءُ في رحمةِ الله لمن تاب وأصلح، ولينُ الجانب."},"action":{"text":"أبشِر برحمة الله إن تبت وأصلحت، وابدأ إخوانك بالسلام والبِشر."}},{"n":55,"reflection":{"text":"«وكذلك نفصل الآيات ولتستبين سبيل المجرمين» — وكما بيّنّا هذه الآيات نفصّل غيرها ونوضّحها ليتبيّن الحقُّ من الباطل، ولتظهر طريقُ المجرمين فتُجتنب؛ فمعرفةُ سبيل الشرّ سبيلٌ لاجتنابه. فالبيانُ يكشف طريقَ الحقّ وطريقَ الإجرام.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ سبيلِ المجرمين لاجتنابها."},"action":{"text":"اعرف طرقَ الشرّ لتجتنبها، فتفصيلُ الآيات يكشف الحقَّ ويُبيّن سبيلَ الباطل."}}]},{"title":"البيّنةُ والحكمُ لله، ومفاتحُ الغيب","range":[56,62],"theme":"البراءةُ من الشرك، وأنّ الحكمَ لله، وسعةُ علمِه بالغيب والشهادة وقبضِه للأرواح","verses":[{"n":56,"reflection":{"text":"«قل إني نهيت أن أعبد الذين تدعون من دون الله قل لا أتبع أهواءكم قد ضللت إذا وما أنا من المهتدين» — قل: نهاني الله أن أعبد ما تعبدون من دونه؛ ولن أتّبع أهواءكم في الشرك، فلو اتّبعتها لضللتُ ولم أكن من المهتدين. فاتّباعُ الهوى في الدين ضلال، والاعتصامُ بالوحي هدى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"رفضُ اتّباعِ الأهواءِ في الدين ولزومُ الوحي."},"action":{"text":"لا تتّبع أهواءَ الناس في دينك، فالهدى في الوحي لا في الأهواء."}},{"n":57,"reflection":{"text":"«قل إني على بينة من ربي وكذبتم به ما عندي ما تستعجلون به إن الحكم إلا لله يقص الحق وهو خير الفاصلين» — قل: أنا على حجّةٍ واضحةٍ من ربّي، وأنتم كذّبتم بها؛ وليس عندي العذابُ الذي تستعجلونه، فأمرُه إلى الله؛ فالحكمُ لله وحده يقضي بالحقّ وهو خيرُ من يفصل بين المحقّ والمبطل. فالحكمُ والعذابُ بيد الله في وقته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ بأنّ الحكمَ لله وحده في وقته وحكمته."},"action":{"text":"سلّم الأمرَ لله، فالحكمُ له وحده، يقضي بالحقّ في الوقت الذي يشاء."}},{"n":58,"reflection":{"text":"«قل لو أن عندي ما تستعجلون به لقضي الأمر بيني وبينكم والله أعلم بالظالمين» — قل: لو كان بيدي العذابُ الذي تستعجلونه لأنزلته بكم فانتهى الأمرُ بيننا؛ لكنّه بيد الله وهو أعلمُ بالظالمين ومتى يأخذهم بحكمته. فتأخيرُ العقوبة حكمةٌ لا عجز.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بحكمة الله في تأخيرِ العقوبة."},"action":{"text":"لا تستعجل قضاءَ الله، فتأخيرُ العقوبة حكمةٌ، وهو أعلمُ بالظالمين."}},{"n":59,"reflection":{"text":"«وعنده مفاتح الغيب لا يعلمها إلا هو ويعلم ما في البر والبحر وما تسقط من ورقة إلا يعلمها ولا حبة في ظلمات الأرض ولا رطب ولا يابس إلا في كتاب مبين» — عند الله وحده خزائنُ الغيب لا يعلمها سواه؛ يعلم كلَّ ما في البرّ والبحر، وما تسقط ورقةٌ من شجرةٍ إلا بعلمه، ولا حبّةٌ في باطن الأرض، ولا رطبٌ ولا يابسٌ إلا وهو مثبتٌ في اللوح المحفوظ؛ فعلمُه محيطٌ بأدقّ الأشياء. فمن أحاط علمُه بكلّ شيءٍ يُراقَب في كلّ شيء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["عالم الغيب"],"heart_state":{"text":"استحضارُ إحاطةِ علمِ الله بأدقّ التفاصيل."},"action":{"text":"راقب اللهَ الذي يعلم سقوطَ الورقة والحبّةَ في الظلمة، فلا يخفى عليه شيءٌ منك."}},{"n":60,"reflection":{"text":"«وهو الذي يتوفاكم بالليل ويعلم ما جرحتم بالنهار ثم يبعثكم فيه ليقضى أجل مسمى ثم إليه مرجعكم ثم ينبئكم بما كنتم تعملون» — هو الذي يقبض أرواحكم في النوم بالليل (وفاةً صغرى) ويعلم ما كسبتم بالنهار، ثمّ يوقظكم في النهار لتكملوا أعماركم؛ ثمّ إليه المرجعُ بالموت، فيخبركم بأعمالكم ويجازيكم. فالنومُ واليقظةُ آيةُ الموت والبعث كلَّ يوم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بالنومِ والاستيقاظِ آيةَ الموت والبعث."},"action":{"text":"تذكّر بنومك واستيقاظك موتَك وبعثك، واستعدّ ليومٍ تُنبَّأ فيه بعملك."}},{"n":61,"reflection":{"text":"«وهو القاهر فوق عباده ويرسل عليكم حفظة حتى إذا جاء أحدكم الموت توفته رسلنا وهم لا يفرطون» — هو الغالبُ فوق عباده، يرسل عليكم ملائكةً يحفظون أعمالكم ويحصونها، حتى إذا حضر أحدَكم الموتُ قبضت روحَه ملائكةُ الموت بلا تقصيرٍ ولا تأخير؛ فالأعمالُ محفوظة، والأجلُ محتوم. فكلُّ عملٍ محصًى، وكلُّ نفسٍ مقبوضةٌ بأجلها.","source":"تفسير السعدي","grade":"ma'thur"},"names":["القاهر"],"heart_state":{"text":"استحضارُ حفظِ الأعمالِ وحتميّةِ قبض الروح."},"action":{"text":"اعلم أنّ عملك محفوظٌ وأجلك محتوم، فاعمل صالحًا قبل أن تقبض روحك."}},{"n":62,"reflection":{"text":"«ثم ردوا إلى الله مولاهم الحق ألا له الحكم وهو أسرع الحاسبين» — ثمّ يُرَدّ العبادُ بعد الموت إلى الله سيّدهم الحقّ؛ ألا له وحده الحكمُ والقضاءُ يومَ القيامة، وهو أسرعُ الحاسبين يحاسب الخلقَ كلَّهم في لحظة؛ فلا مفرّ من حكمه. فالمرجعُ إلى الله، والحكمُ له، والحسابُ سريع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["المولى","أسرع الحاسبين"],"heart_state":{"text":"الاستعدادُ للردّ إلى الله وسرعةِ حسابه."},"action":{"text":"استعدّ للقاء الله مولاك الحقّ، فإليه المرجع، وهو أسرعُ الحاسبين."}}]},{"title":"الله ينجّيكم من كلّ كرب، وقدرتُه على العذاب","range":[63,67],"theme":"إخلاصُ الدعاءِ عند الكرب لله، ونقضُ الشركِ بعد النجاة، وقدرةُ الله على أنواع العذاب","verses":[{"n":63,"reflection":{"text":"«قل من ينجيكم من ظلمات البر والبحر تدعونه تضرعا وخفية لئن أنجانا من هذه لنكونن من الشاكرين» — قل: من ينقذكم من شدائد البرّ والبحر حين تدعونه متضرّعين سرًّا وعلانيةً، وتعاهدونه: لئن أنجيتنا لنشكرنّك؟ إنّه الله وحده. فعند الشدّة تخلص القلوبُ لله وتعاهد على الشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ الدعاءِ لله عند الشدائد والوفاءُ بالشكر."},"action":{"text":"إذا اشتدّ بك الكرب فادعُ الله وحده، وأوفِ بما عاهدته عليه من الشكر."}},{"n":64,"reflection":{"text":"«قل الله ينجيكم منها ومن كل كرب ثم أنتم تشركون» — قل: الله وحده ينجّيكم من تلك الشدّة ومن كلّ همٍّ وكرب؛ ثمّ أنتم — بعد النجاة — تعودون إلى الشرك وتنسون فضله! فما أعظمَ جحودَ من نجّاه الله ثمّ أشرك به. فالوفاءُ لله بعد النجاة توحيدٌ وشكر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الوفاءُ لله بعد النجاة وعدمُ العودةِ للغفلة."},"action":{"text":"إذا نجّاك الله من كربٍ فلا تعُد إلى الغفلة والذنب، بل ازدد له شكرًا وتوحيدًا."}},{"n":65,"reflection":{"text":"«قل هو القادر على أن يبعث عليكم عذابا من فوقكم أو من تحت أرجلكم أو يلبسكم شيعا ويذيق بعضكم بأس بعض انظر كيف نصرف الآيات لعلهم يفقهون» — قل: الله قادرٌ أن يرسل عليكم عذابًا من فوقكم (كالصواعق) أو من تحتكم (كالخسف)، أو يجعلكم فرقًا متناحرةً يذيق بعضُكم بأسَ بعض؛ انظر كيف نصرّف الآياتِ لعلّهم يفهمون؛ (وقد استعاذ النبيُّ ﷺ من الأوّلين فأُعيذ، وسأل ألّا يجعل بأسهم بينهم فمُنع). فاختلافُ الأمّة عذابٌ نسأل الله العافية منه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعاذةُ من العذاب ومن الفرقةِ والاقتتال."},"action":{"text":"اسأل الله العافيةَ من العذاب ومن فرقة الأمّة، واسعَ في جمع الكلمة لا تفريقها."}},{"n":66,"reflection":{"text":"«وكذب به قومك وهو الحق قل لست عليكم بوكيل» — وكذّب قومُك يا محمد بالقرآن وهو الحقُّ الذي لا شكّ فيه؛ قل: لست موكّلًا بحفظكم وإجباركم على الإيمان، إنّما أنا مبلّغ؛ فالحسابُ على الله. فمهمّةُ الداعي البلاغ، والهدايةُ على الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أداءُ البلاغ وتركُ الهداية لله."},"action":{"text":"بلّغ الحقّ ولا تحمل همّ إجبار الناس، فلست وكيلًا عليهم بل مبلّغًا."}},{"n":67,"reflection":{"text":"«لكل نبإ مستقر وسوف تعلمون» — لكلّ خبرٍ أخبر الله به وقتٌ يستقرّ فيه ويقع لا محالة؛ وسوف تعلمون صدقَ ما أُخبرتم به من الوعد والوعيد حين يقع. فوعدُ الله وخبرُه واقعٌ في وقته المقدّر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ خبرَ الله واقعٌ في وقته."},"action":{"text":"صدّق بوعد الله ووعيده، فكلُّ خبرٍ منه له وقتٌ يقع فيه لا محالة."}}]},{"title":"الإعراضُ عن الخائضين، وتذكيرٌ بالحساب","range":[68,73],"theme":"هجرُ مجالسِ الاستهزاء بالآيات، وأنّ لا شفيعَ يوم القيامة، وعظمةُ الخالقِ صاحبِ الملك","verses":[{"n":68,"reflection":{"text":"«وإذا رأيت الذين يخوضون في آياتنا فأعرض عنهم حتى يخوضوا في حديث غيره وإما ينسينك الشيطان فلا تقعد بعد الذكرى مع القوم الظالمين» — إذا رأيت من يخوضون في آيات الله بالاستهزاء والتكذيب فأعرض عنهم حتى يتحوّلوا إلى حديثٍ آخر؛ فإن أنساك الشيطانُ فقعدت فلا تستمرّ بعد التذكّر مع الظالمين. فمجالسُ الاستهزاء بالدين تُهجَر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"هجرُ مجالسِ الخوضِ في آيات الله بالباطل."},"action":{"text":"إذا سمعت استهزاءً بآيات الله في مجلسٍ فقُم عنه، ولا تستمرّ بعد التذكّر."}},{"n":69,"reflection":{"text":"«وما على الذين يتقون من حسابهم من شيء ولكن ذكرى لعلهم يتقون» — ليس على المتّقين إثمٌ من حساب الخائضين إذا جالسوهم للتذكير والنصح لا للرضا؛ لكن عليهم أن يذكّروهم لعلّهم يتّقون ويكفّون؛ فالمجالسةُ للاحتساب لا للإقرار. فالمقصودُ التذكيرُ لا الرضا بالمنكر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المجالسةُ للتذكير والنصحِ لا للرضا بالباطل."},"action":{"text":"إن خالطت مخطئًا فلتذكيره ونصحه، لا لإقراره على باطله."}},{"n":70,"reflection":{"text":"«وذر الذين اتخذوا دينهم لعبا ولهوا وغرتهم الحياة الدنيا وذكر به أن تبسل نفس بما كسبت ليس لها من دون الله ولي ولا شفيع... لهم شراب من حميم وعذاب أليم بما كانوا يكفرون» — اترك الذين جعلوا دينهم لهوًا وخدعتهم الدنيا؛ وذكّر بالقرآن لئلّا تُسلَم نفسٌ للهلاك بذنبها، فليس لها وليٌّ ولا شفيعٌ سوى الله، ولو بذلت كلَّ فداءٍ لم يُقبل؛ أولئك أُسلموا للعذاب: لهم شرابٌ من ماءٍ حارٍّ وعذابٌ أليم بكفرهم. فلا فداءَ ولا شفيعَ يومئذٍ إلا بإذن الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ قبل يومٍ لا وليَّ فيه ولا شفيعَ ولا فداء."},"action":{"text":"اعمل لنجاة نفسك، فلا يفديها مالٌ ولا شفيعٌ يومَ القيامة إلا رحمةُ الله."}},{"n":71,"reflection":{"text":"«قل أندعو من دون الله ما لا ينفعنا ولا يضرنا ونرد على أعقابنا بعد إذ هدانا الله كالذي استهوته الشياطين في الأرض حيران له أصحاب يدعونه إلى الهدى ائتنا قل إن هدى الله هو الهدى وأمرنا لنسلم لرب العالمين» — قل: أنعبد ما لا ينفع ولا يضرّ، ونرجع كفّارًا بعد أن هدانا الله؟ فنكون كمن أضلّته الشياطين في مهامه الأرض حيران، وأصحابُه على الطريق ينادونه أن ارجع إلينا وهو لا يستجيب؛ قل: هدى الله هو الهدى الحقّ، وأُمرنا أن نُسلم لربّ العالمين. فالرجوعُ عن الهدى بعد معرفته حيرةٌ وهلاك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على هدى الله بعد معرفتِه."},"action":{"text":"اثبت على الهدى بعد أن منّ الله به عليك، ولا ترجع إلى ضلالٍ بعد نور."}},{"n":72,"reflection":{"text":"«وأن أقيموا الصلاة واتقوه وهو الذي إليه تحشرون» — وأُمرنا أن نقيم الصلاة تامّةً ونتّقي الله في كلّ أمرنا؛ وهو الذي إليه تُجمعون يومَ القيامة للحساب؛ فأقيموا الصلاةَ استعدادًا للقائه. فالصلاةُ والتقوى زادُ يوم الحشر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إقامةُ الصلاةِ والتقوى استعدادًا للحشر."},"action":{"text":"أقم صلاتك واتّقِ الله، مستحضرًا أنّك إليه تُحشر فتُجازى."}},{"n":73,"reflection":{"text":"«وهو الذي خلق السماوات والأرض بالحق ويوم يقول كن فيكون قوله الحق وله الملك يوم ينفخ في الصور عالم الغيب والشهادة وهو الحكيم الخبير» — هو الذي خلق الكونَ بالحقّ لا عبثًا، وإذا أراد شيئًا قال له كن فيكون؛ قولُه الحقُّ النافذ، وله الملكُ المطلقُ يومَ ينفخ إسرافيلُ في الصور للبعث؛ عالمُ ما غاب وما حضر، الحكيمُ في خلقه، الخبيرُ بخفايا الأمور. فمن هذا شأنُه هو المعبودُ وحده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["عالم الغيب والشهادة","الحكيم","الخبير"],"heart_state":{"text":"تعظيمُ الخالقِ صاحبِ الأمرِ النافذِ والملكِ يومَ البعث."},"action":{"text":"عظّم اللهَ الذي يقول للشيء كن فيكون، وله الملك، فأخلِص له العبادة."}}]},{"title":"حجّةُ إبراهيم: من الكوكب إلى فاطرِ السماوات","range":[74,79],"theme":"مناظرةُ إبراهيم أباه وقومه، ونظرُه في الأفول ليصل إلى توحيدِ الفاطر","verses":[{"n":74,"reflection":{"text":"«وإذ قال إبراهيم لأبيه آزر أتتخذ أصناما آلهة إني أراك وقومك في ضلال مبين» — واذكر إذ قال إبراهيمُ لأبيه آزر ناصحًا: أتعبد أصنامًا لا تنفع ولا تضرّ؟ إنّي أراك وقومك في ضلالٍ ظاهر؛ فبدأ بالنصح لأقرب الناس إليه برفقٍ وصدق. فالدعوةُ تبدأ بالأقربين برفق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"نصحُ الأقربين بالتوحيد برفقٍ وصدق."},"action":{"text":"ابدأ بدعوة أهلك وأقربيك إلى التوحيد برفقٍ وحكمة كما فعل إبراهيم."}},{"n":75,"reflection":{"text":"«وكذلك نري إبراهيم ملكوت السماوات والأرض وليكون من الموقنين» — وكما بصّرناه ضلالَ قومه، أريناه عظيمَ ملكِ الله في السماوات والأرض وبديعَ صنعه، ليزداد يقينًا ويستدلّ به على وحدانيّة الخالق؛ فالتفكّرُ في الملكوت يورث اليقين. فالنظرُ في خلق الله بابُ اليقين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في ملكوت السماوات والأرض لزيادةِ اليقين."},"action":{"text":"تأمّل عظمةَ خلق الله في الكون، فالنظرُ في ملكوته يزيدك يقينًا بوحدانيّته."}},{"n":76,"reflection":{"text":"«فلما جن عليه الليل رأى كوكبا قال هذا ربي فلما أفل قال لا أحب الآفلين» — لمّا أظلم عليه الليل رأى كوكبًا لامعًا فقال — على سبيل التنزّل مع قومه ليُبطل عبادة النجوم —: هذا ربّي؛ فلمّا غاب قال: لا أحبّ الآلهةَ التي تغيب وتزول؛ فالربُّ لا يأفل. فالمعبودُ الحقُّ لا يغيب ولا يزول.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ ما يزول ويأفل لا يصلح إلهًا."},"action":{"text":"لا تعلّق قلبك بزائلٍ، فالمعبودُ الحقُّ باقٍ لا يأفل ولا يزول."}},{"n":77,"reflection":{"text":"«فلما رأى القمر بازغا قال هذا ربي فلما أفل قال لئن لم يهدني ربي لأكونن من القوم الضالين» — فلمّا رأى القمرَ طالعًا أكبرَ من الكوكب قال: هذا ربّي، فلمّا غاب قال: لئن لم يوفّقني ربّي للهدى لأكوننّ من الضالّين؛ فأظهر افتقارَه إلى هداية الله. فالهدايةُ بتوفيق الله لا بمجرّد النظر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الافتقارُ إلى الله في طلبِ الهداية."},"action":{"text":"اطلب الهدايةَ من الله وافتقر إليه، فلا يهتدي أحدٌ إلا بتوفيقه."}},{"n":78,"reflection":{"text":"«فلما رأى الشمس بازغة قال هذا ربي هذا أكبر فلما أفلت قال يا قوم إني بريء مما تشركون» — فلمّا رأى الشمسَ طالعةً أكبرَ من القمر قال: هذا ربّي هذا أكبر، فلمّا غابت أعلن نتيجةَ الحجّة: يا قوم إنّي بريءٌ من كلّ ما تشركونه بالله؛ فما دام كلُّها يأفل فلا يصلح ربًّا. فالبراءةُ من الشرك ثمرةُ النظر الصادق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"البراءةُ من الشركِ بعد وضوحِ الحجّة."},"action":{"text":"تبرّأ من كلّ معبودٍ سوى الله، فالكواكبُ كلُّها آفلةٌ مخلوقةٌ لا تُعبد."}},{"n":79,"reflection":{"text":"«إني وجهت وجهي للذي فطر السماوات والأرض حنيفا وما أنا من المشركين» — أعلن إبراهيمُ توحيدَه الخالص: وجّهتُ عبادتي وقصدي للذي أبدع السماواتِ والأرضَ، مائلًا عن الشرك إلى التوحيد، ولستُ من المشركين؛ فأخلص وجهه لفاطر الكون. فالتوحيدُ توجيهُ القلبِ كلِّه للخالق وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توجيهُ القلبِ والعبادةِ لفاطرِ السماوات وحده."},"action":{"text":"وجّه قلبك وعبادتك لله فاطرِ الكون وحده، حنيفًا مخلصًا لا تشرك به شيئًا."}}]},{"title":"حجّةُ إبراهيم على قومه، والأمنُ لأهل التوحيد","range":[80,83],"theme":"ثباتُ الموحّدِ وعدمُ خوفه من الشركاء، وأنّ الأمنَ لمن لم يخلط إيمانه بشرك","verses":[{"n":80,"reflection":{"text":"«وحاجه قومه قال أتحاجوني في الله وقد هدان ولا أخاف ما تشركون به إلا أن يشاء ربي شيئا وسع ربي كل شيء علما أفلا تتذكرون» — جادله قومُه في التوحيد، فقال: أتجادلونني في الله وقد هداني إليه؟ ولا أخاف آلهتكم فإنّها لا تضرّ إلا أن يشاء الله؛ وسع علمُ ربّي كلَّ شيء؛ أفلا تتذكّرون فتعتبروا؟ فالموحّدُ لا يخاف إلا الله. فمن هداه الله لا تزلزله شبهات.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على التوحيدِ وعدمُ الخوفِ من غير الله."},"action":{"text":"اثبت على توحيدك ولا تخف من معبوداتٍ لا تملك ضرًّا ولا نفعًا."}},{"n":81,"reflection":{"text":"«وكيف أخاف ما أشركتم ولا تخافون أنكم أشركتم بالله ما لم ينزل به عليكم سلطانا فأي الفريقين أحق بالأمن إن كنتم تعلمون» — كيف أخاف أصنامكم العاجزة وأنتم لا تخافون إشراككم بالله ما لا حجّةَ لكم عليه؟ فأيُّ الفريقين أحقُّ بالأمن: الموحّدُ أم المشرك؟ إن كنتم تعقلون فالموحّدُ أحقّ. فالأمنُ الحقيقيّ لأهل التوحيد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ أهلَ التوحيدِ أحقُّ بالأمن."},"action":{"text":"اطلب الأمنَ في التوحيد، فالموحّدُ آمنٌ والمشركُ خائفٌ وإن لم يشعر."}},{"n":82,"reflection":{"text":"«الذين آمنوا ولم يلبسوا إيمانهم بظلم أولئك لهم الأمن وهم مهتدون» — الذين آمنوا ولم يخلطوا إيمانهم بشرك (والظلمُ هنا الشرك، كما فسّره النبيُّ ﷺ بآية لقمان «إنّ الشرك لظلم عظيم») لهم الأمنُ التامّ من العذاب وهم المهتدون؛ فطمأنت الآيةُ الصحابةَ حين خافوا أن يكون كلُّ ظلمٍ مرادًا. فالأمنُ الكاملُ لمن سلم توحيده من الشرك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الأمنِ بسلامةِ التوحيدِ من الشرك."},"action":{"text":"نقِّ توحيدك من الشرك دقيقِه وجليله، فبه يكون لك الأمنُ والهداية."}},{"n":83,"reflection":{"text":"«وتلك حجتنا آتيناها إبراهيم على قومه نرفع درجات من نشاء إن ربك حكيم عليم» — تلك الحجّةُ البالغةُ التي احتجّ بها إبراهيمُ على قومه من عندنا وفّقناه لها؛ ونرفع في العلم والإيمان درجاتِ من نشاء من عبادنا؛ إنّ ربّك حكيمٌ يضع الأشياء مواضعها، عليمٌ بمن يستحقّ الرفعة. فالحجّةُ توفيقٌ، والرفعةُ بعلمٍ وحكمة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الحكيم","العليم"],"heart_state":{"text":"طلبُ رفعةِ الدرجاتِ بالعلمِ والحجّةِ من الله."},"action":{"text":"اطلب من الله أن يرفع درجتك بالعلم والحجّة، فالتوفيقُ منه وحده."}}]},{"title":"سلسلةُ الأنبياء المهديّين، والاقتداءُ بهم","range":[84,90],"theme":"تعدادُ الأنبياء الذين هداهم الله، وأنّ الشركَ يُحبط العمل، والأمرُ بالاقتداء بهداهم","verses":[{"n":84,"reflection":{"text":"«ووهبنا له إسحاق ويعقوب كلا هدينا ونوحا هدينا من قبل ومن ذريته داود وسليمان وأيوب ويوسف وموسى وهارون وكذلك نجزي المحسنين» — وهبنا لإبراهيم إسحاقَ ويعقوبَ وهديناهما، وهدينا نوحًا قبله، ومن ذرّيّته داودَ وسليمانَ وأيّوبَ ويوسفَ وموسى وهارون؛ وكذلك نجزي المحسنين بالهداية والذرّيّة الصالحة. فجزاءُ الإحسان الهدايةُ والذرّيّةُ المباركة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["المحسنين"],"heart_state":{"text":"الإحسانُ سببُ الهدايةِ والذرّيّةِ الصالحة."},"action":{"text":"أحسِن في عملك ودعائك، فالله يجزي المحسنين بالهداية والذرّيّة الصالحة."}},{"n":85,"reflection":{"text":"«وزكريا ويحيى وعيسى وإلياس كل من الصالحين» — وهدينا زكريّا ويحيى وعيسى وإلياس؛ كلُّهم من الصالحين الكاملين في الصلاح؛ فالصلاحُ جامعُ صفاتهم. فالصلاحُ غايةٌ يشترك فيها كلُّ الأنبياء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بالصالحين من أنبياء الله."},"action":{"text":"اجعل الصلاحَ غايتك، مقتديًا بأنبياء الله الصالحين في إيمانهم وعملهم."}},{"n":86,"reflection":{"text":"«وإسماعيل واليسع ويونس ولوطا وكلا فضلنا على العالمين» — وهدينا إسماعيلَ واليسعَ ويونسَ ولوطًا؛ وكلَّ هؤلاء الأنبياء فضّلناهم على عالمي زمانهم بالنبوّة والرسالة. فالنبوّةُ أعظمُ تفضيلٍ وشرف.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ منزلةِ الأنبياء الذين فضّلهم الله."},"action":{"text":"عظّم أنبياءَ الله الذين اصطفاهم وفضّلهم، واتّبع سبيلهم."}},{"n":87,"reflection":{"text":"«ومن آبائهم وذرياتهم وإخوانهم واجتبيناهم وهديناهم إلى صراط مستقيم» — وهدينا من آبائهم وذرّيّاتهم وإخوانهم من صلح، واصطفيناهم لرسالتنا، ووفّقناهم إلى الطريق المستقيم؛ فالهدايةُ اصطفاءٌ من الله. فالهدايةُ نعمةٌ يمنّ الله بها على من اصطفى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الهدايةِ والاصطفاء."},"action":{"text":"اشكر الله إن هداك واصطفاك للحقّ، واسأله الثباتَ على صراطه المستقيم."}},{"n":88,"reflection":{"text":"«ذلك هدى الله يهدي به من يشاء من عباده ولو أشركوا لحبط عنهم ما كانوا يعملون» — ذلك الذي وُفّق إليه الأنبياء هو هدى الله يهدي به من يشاء من عباده؛ ولو أنّ هؤلاء الأنبياء — مع علوّ مقامهم — أشركوا لبطلت أعمالهم؛ فكيف بغيرهم؟ فالشركُ يُحبط أعظمَ الأعمال. فاحذر الشركَ فإنّه يُحبط العمل كلَّه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الشركِ الذي يُحبط العمل ولو عظُم."},"action":{"text":"احفظ توحيدك، فالشركُ يُحبط العملَ كلَّه ولو كان صاحبُه نبيًّا."}},{"n":89,"reflection":{"text":"«أولئك الذين آتيناهم الكتاب والحكم والنبوة فإن يكفر بها هؤلاء فقد وكلنا بها قوما ليسوا بها بكافرين» — أولئك الأنبياءُ آتيناهم الكتبَ والفهمَ والنبوّة؛ فإن يكفر بهذه النعم قومُك يا محمد فقد هيّأنا لها قومًا (كالمهاجرين والأنصار ومن تبعهم) يؤمنون بها ولا يكفرون؛ فدينُ الله لا يضيع بكفر الكافرين. فالحقُّ محفوظٌ يحمله من يؤمن به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ الحقَّ محفوظٌ يحمله المؤمنون."},"action":{"text":"اثبت على الحقّ، فإن أعرض عنه قومٌ حمله آخرون، ودينُ الله باقٍ لا يضيع."}},{"n":90,"reflection":{"text":"«أولئك الذين هدى الله فبهداهم اقتده قل لا أسألكم عليه أجرا إن هو إلا ذكرى للعالمين» — أولئك الأنبياءُ الذين هداهم الله، فاقتدِ يا محمد بهداهم في التوحيد والصبر ومكارم الأخلاق؛ وقل: لا أطلب على تبليغ القرآن أجرًا، ما هو إلا تذكرةٌ للعالمين كلِّهم. فالاقتداءُ بالأنبياء منهجٌ، والدعوةُ لله لا للأجر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بهدى الأنبياءِ والإخلاصُ في الدعوة."},"action":{"text":"اقتدِ بهدى الأنبياء في توحيدك وأخلاقك، وادعُ إلى الله لوجهه لا لأجر."}}]},{"title":"ما قدروا الله حقّ قدره، وبركةُ القرآن","range":[91,94],"theme":"جحودُ من أنكر الوحي، وبركةُ القرآن، وأظلمُ الناسِ مفترٍ، وهولُ الموتِ للظالمين","verses":[{"n":91,"reflection":{"text":"«وما قدروا الله حق قدره إذ قالوا ما أنزل الله على بشر من شيء قل من أنزل الكتاب الذي جاء به موسى نورا وهدى للناس تجعلونه قراطيس تبدونها وتخفون كثيرا... قل الله ثم ذرهم في خوضهم يلعبون» — ما عظّموا الله حقَّ عظمته إذ أنكروا إنزالَ الوحي على البشر؛ قل: من أنزل التوراةَ على موسى نورًا وهدًى، التي تكتبونها أوراقًا تُظهرون بعضها وتُخفون كثيرًا (كصفة النبيّ)؟ إنّه الله؛ ثمّ اتركهم في باطلهم يلعبون. فإنكارُ الوحي جهلٌ بقدر الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ الله حقَّ قدرِه بالإيمان بوحيه."},"action":{"text":"عظّم اللهَ حقَّ قدره، وآمن بأنّه أنزل الوحيَ رحمةً وهدًى للناس."}},{"n":92,"reflection":{"text":"«وهذا كتاب أنزلناه مبارك مصدق الذي بين يديه ولتنذر أم القرى ومن حولها والذين يؤمنون بالآخرة يؤمنون به وهم على صلاتهم يحافظون» — وهذا القرآنُ كتابٌ أنزلناه كثيرَ الخير والبركة، مصدّقًا للكتب قبله، لتنذر به مكّةَ (أمَّ القرى) ومن حولها من الناس أجمعين؛ والذين يؤمنون بالآخرة يؤمنون به لأنّهم يخافون الحساب، وهم يحافظون على صلواتهم؛ فعلامةُ الإيمان بالقرآن المحافظةُ على الصلاة. فبركةُ القرآن في هدايته والعملِ به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ بركةِ القرآن والمحافظةُ على الصلاة."},"action":{"text":"اقرأ القرآنَ المبارك واعمل به، وحافظ على صلاتك، فذاك علامةُ الإيمان به."}},{"n":93,"reflection":{"text":"«ومن أظلم ممن افترى على الله كذبا أو قال أوحي إلي ولم يوح إليه شيء ومن قال سأنزل مثل ما أنزل الله ولو ترى إذ الظالمون في غمرات الموت والملائكة باسطو أيديهم أخرجوا أنفسكم اليوم تجزون عذاب الهون بما كنتم تقولون على الله غير الحق وكنتم عن آياته تستكبرون» — لا أظلمَ ممّن كذب على الله، أو ادّعى الوحيَ كذبًا، أو زعم أنّه يأتي بمثل القرآن؛ ولو ترى الظالمين في سكرات الموت والملائكةُ تبسط أيديها بالعذاب: أخرجوا أنفسكم! اليوم تُجزَون عذابَ الذلّ بما كنتم تقولون على الله الباطلَ وتستكبرون عن آياته؛ لرأيت هولًا عظيمًا. فالكذبُ على الله والاستكبارُ عن آياته أظلمُ الظلم وأشدُّه عاقبة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقّي الكذبِ على الله والاستكبارِ عن آياته."},"action":{"text":"لا تقُل على الله ما لم يقُل، ولا تستكبر عن آياته، فعاقبةُ ذلك عذابُ الهون."}},{"n":94,"reflection":{"text":"«ولقد جئتمونا فرادى كما خلقناكم أول مرة وتركتم ما خولناكم وراء ظهوركم وما نرى معكم شفعاءكم الذين زعمتم أنهم فيكم شركاء لقد تقطع بينكم وضل عنكم ما كنتم تزعمون» — يقال لهم يومَ القيامة: جئتمونا منفردين بلا مالٍ ولا أهلٍ ولا شفيع، كما خلقناكم أوّلَ مرّةٍ عراةً حفاةً، وتركتم ما أعطيناكم من المال خلف ظهوركم؛ ولا نرى معكم شفعاءكم الذين زعمتموهم شركاء؛ لقد انقطعت الوصلُ بينكم وغاب عنكم ما كنتم تزعمون. فيأتي العبدُ فردًا بلا ما اتّكل عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للقاء الله فردًا بلا مالٍ ولا شفيعٍ سواه."},"action":{"text":"اعمل صالحًا تلقى الله به، فستأتيه فردًا، ويتخلّى عنك كلُّ ما سواه."}}]},{"title":"آياتُ الخلق: فالقُ الحبِّ والإصباح","range":[95,100],"theme":"دلائلُ التوحيد في الحبّ والنوى والصبح والليل والنجوم والنبات، وبطلانُ نسبةِ الشركاء والولد","verses":[{"n":95,"reflection":{"text":"«إن الله فالق الحب والنوى يخرج الحي من الميت ومخرج الميت من الحي ذلكم الله فأنى تؤفكون» — إنّ الله يشقّ الحبّةَ والنواةَ فيُخرج منها الزرعَ والنخل؛ ويُخرج الحيَّ من الميّت (كالنبات من الحبّة، والإنسان من النطفة)، والميّتَ من الحيّ (كالبيضة من الطير)؛ ذلكم الله الخالق، فكيف تُصرَفون عن عبادته إلى غيره؟ فمن يفعل هذا وحده هو المعبود.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في إخراجِ الحيّ من الميّت دليلًا على التوحيد."},"action":{"text":"تأمّل في الحبّة تنشقّ عن زرع، فمن يُحيي بها الأرضَ هو الله وحده، فاعبده."}},{"n":96,"reflection":{"text":"«فالق الإصباح وجعل الليل سكنا والشمس والقمر حسبانا ذلك تقدير العزيز العليم» — يشقّ ظلمةَ الليل بضياء الصبح، وجعل الليلَ راحةً وسكونًا للأبدان، والشمسَ والقمرَ يجريان بحسابٍ دقيقٍ تُعرف به الأوقات والسنون؛ ذلك تقديرُ العزيز الذي لا يُغالَب، العليمِ بمصالح خلقه. فنظامُ الكون آيةُ عزّةٍ وعلم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["العزيز","العليم"],"heart_state":{"text":"التفكّرُ في نظامِ الليلِ والنهارِ والفلك."},"action":{"text":"تأمّل انشقاقَ الصبح وسكونَ الليل ودقّةَ حساب الشمس والقمر، فذاك تقديرُ العزيز العليم."}},{"n":97,"reflection":{"text":"«وهو الذي جعل لكم النجوم لتهتدوا بها في ظلمات البر والبحر قد فصلنا الآيات لقوم يعلمون» — هو الذي جعل النجومَ زينةً ومنارًا تهتدون بها في ظلمات البرّ والبحر إلى مقاصدكم؛ قد بيّنّا الآياتِ لقومٍ يعلمون فينتفعون بها. فالنجومُ نعمةٌ للاهتداء بها في الأسفار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ النجومِ والاهتداءِ بها."},"action":{"text":"اشكر الله على نعمة النجوم التي تهتدي بها، وتأمّل في دلائل التوحيد فيها."}},{"n":98,"reflection":{"text":"«وهو الذي أنشأكم من نفس واحدة فمستقر ومستودع قد فصلنا الآيات لقوم يفقهون» — هو الذي خلقكم جميعًا من نفسٍ واحدة (آدم)؛ فلكم مستقرٌّ في الأرحام أو على ظهر الأرض، ومستودعٌ في الأصلاب أو القبور؛ قد بيّنّا الآياتِ لقومٍ يفقهون معانيها. فأصلُكم واحد، وأطواركم بيد الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في أصلِ الخلقِ وأطوارِه."},"action":{"text":"تأمّل أنّ أصلك من نفسٍ واحدة، وأنّ الله ينقلك في أطوارٍ من صلبٍ إلى رحمٍ إلى قبر."}},{"n":99,"reflection":{"text":"«وهو الذي أنزل من السماء ماء فأخرجنا به نبات كل شيء فأخرجنا منه خضرا نخرج منه حبا متراكبا ومن النخل من طلعها قنوان دانية وجنات من أعناب والزيتون والرمان مشتبها وغير متشابه انظروا إلى ثمره إذا أثمر وينعه إن في ذلكم لآيات لقوم يؤمنون» — هو الذي أنزل المطرَ فأنبت به كلَّ أنواع النبات: الزرعَ ذا الحبّ المتراكب، والنخلَ ذا العناقيد الدانية، وجنّاتِ الأعناب والزيتونِ والرمّان، متشابهًا في الشكل مختلفًا في الطعم؛ انظروا إلى الثمر حين يظهر ثمّ ينضج؛ إنّ في ذلك لآياتٍ لقومٍ يؤمنون. فاختلافُ الثمار من ماءٍ واحدٍ آيةٌ على القدرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في النباتِ والثمرِ آيةً على القدرة."},"action":{"text":"تأمّل الثمرةَ كيف تنشأ وتنضج من ماءٍ واحدٍ وأرضٍ واحدة، فذاك آيةُ قدرةِ الله."}},{"n":100,"reflection":{"text":"«وجعلوا لله شركاء الجن وخلقهم وخرقوا له بنين وبنات بغير علم سبحانه وتعالى عما يصفون» — ومع كلّ هذه الآيات جعل المشركون لله شركاء من الجنّ يعبدونهم، والله خلقهم؛ واختلقوا له بنين وبنات (كقولهم الملائكةُ بناتُ الله) بلا علمٍ ولا دليل؛ تنزّه الله وتعالى عمّا يصفونه به من النقص. فنسبةُ الشريك والولد افتراءٌ يتنزّه الله عنه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["سبحانه"],"heart_state":{"text":"تنزيهُ الله عن الشريكِ والولدِ وكلِّ نقص."},"action":{"text":"نزّه الله عن كلّ ما لا يليق به من شريكٍ أو ولد، فهو الخالقُ المنزّه."}}]},{"title":"بديعُ السماوات، ولا تدركه الأبصار","range":[101,103],"theme":"تنزيهُ الخالقِ عن الولد، وأنّه خالقُ كلِّ شيءٍ، لطيفٌ لا تدركه الأبصار","verses":[{"n":101,"reflection":{"text":"«بديع السماوات والأرض أنى يكون له ولد ولم تكن له صاحبة وخلق كل شيء وهو بكل شيء عليم» — مبدعُ السماوات والأرض على غير مثالٍ سبق؛ كيف يكون له ولدٌ ولا زوجةَ له، والولدُ يكون عن صاحبة؟ وهو خالقُ كلِّ شيء، فكيف يكون بعضُ خلقه ولدًا له؟ وهو بكلّ شيءٍ عليم. فنسبةُ الولد إليه محالٌ عقلًا وشرعًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["البديع","العليم"],"heart_state":{"text":"تنزيهُ الخالقِ عن الصاحبةِ والولد."},"action":{"text":"نزّه الله الخالقَ عن الولد والصاحبة، فهو خالقُ كلِّ شيءٍ لا يشبهه شيء."}},{"n":102,"reflection":{"text":"«ذلكم الله ربكم لا إله إلا هو خالق كل شيء فاعبدوه وهو على كل شيء وكيل» — ذلكم الموصوفُ بهذه الصفات هو الله ربّكم، لا معبودَ بحقٍّ سواه، خالقُ كلِّ شيء؛ فأخلصوا له العبادة؛ وهو القائمُ على كلّ شيءٍ بالحفظ والتدبير. فمن كان خالقًا مدبّرًا هو المستحقُّ للعبادة والتوكّل.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الوكيل"],"heart_state":{"text":"إفرادُ الخالقِ المدبّرِ بالعبادةِ والتوكّل."},"action":{"text":"اعبد اللهَ وحده خالقَ كلّ شيء، وتوكّل عليه، فهو الوكيلُ القائمُ بأمرك."}},{"n":103,"reflection":{"text":"«لا تدركه الأبصار وهو يدرك الأبصار وهو اللطيف الخبير» — لا تحيط به الأبصارُ إحاطةً في الدنيا (ويراه المؤمنون في الآخرة كما تواتر)، وهو يدرك الأبصارَ ويحيط بها؛ وهو اللطيفُ بعباده يوصل إليهم مصالحهم بلطفه، الخبيرُ بدقائق الأمور؛ فعظمتُه فوق الإدراك، ولطفُه وخبرتُه تحيط بك. فتنزيهٌ عن الإحاطة، وإثباتُ لطفه وخبرته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["اللطيف","الخبير"],"heart_state":{"text":"تعظيمُ الله اللطيفِ الخبيرِ الذي لا تحيط به الأبصار."},"action":{"text":"عظّم اللهَ الذي لا تدركه الأبصار وهو يراك، واطمئن إلى لطفه وخبرته بك."}}]},{"title":"البصائرُ والوحي، والنهيُ عن سبِّ آلهةِ المشركين","range":[104,110],"theme":"القرآنُ بصائرُ لمن أبصر، واتّباعُ الوحي، وحفظُ حرمةِ التوحيدِ حتى في الجدال","verses":[{"n":104,"reflection":{"text":"«قد جاءكم بصائر من ربكم فمن أبصر فلنفسه ومن عمي فعليها وما أنا عليكم بحفيظ» — قد جاءكم من ربّكم حججٌ وبيّناتٌ تُبصر بها القلوبُ الحقَّ؛ فمن أبصر بها فنفعُه لنفسه، ومن عمي عنها فضررُه على نفسه؛ ولستُ حفيظًا أحاسبكم، إنّما أنا مبلّغ. فالانتفاعُ بالبصائر أو الحرمانُ منها يعود على صاحبه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإبصارُ بالقرآنِ والانتفاعُ به لنفسك."},"action":{"text":"افتح قلبك لبصائر القرآن، فمن أبصر بها فلنفسه، ومن أعرض فعلى نفسه."}},{"n":105,"reflection":{"text":"«وكذلك نصرف الآيات وليقولوا درست ولنبينه لقوم يعلمون» — وكما بيّنّا الآياتِ نصرّفها بأنواع البيان؛ فيقول المعاندون: تعلّمتَها من غيرك؛ لكنّ الحكمةَ أن نبيّن الحقَّ لقومٍ يعلمون فينتفعون؛ فالبيانُ يهدي الطالبَ ويقيم الحجّةَ على المعاند. فالآياتُ تُصرّف رحمةً بالمهتدي وحجّةً على المعاند.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الانتفاعُ بتصريفِ الآياتِ لا معارضتُها."},"action":{"text":"تدبّر تنوّعَ بيان القرآن لتنتفع، ولا تكن كمن يعارضه بالتّهم."}},{"n":106,"reflection":{"text":"«اتبع ما أوحي إليك من ربك لا إله إلا هو وأعرض عن المشركين» — اتّبع يا محمد ما أوحاه الله إليك والزمه، فلا معبودَ بحقٍّ سواه؛ وأعرض عن المشركين ولا يشغلك عنادُهم؛ فمهمّتُك الاتّباعُ والبلاغ. فسبيلُ النجاة اتّباعُ الوحي والإعراضُ عن أهل الباطل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ الوحي والإعراضُ عن أهل الباطل."},"action":{"text":"اتّبع الوحيَ والزمه، وأعرض عمّن يعاند الحقّ، فمهمّتُك البلاغ لا الجدال العقيم."}},{"n":107,"reflection":{"text":"«ولو شاء الله ما أشركوا وما جعلناك عليهم حفيظا وما أنت عليهم بوكيل» — لو شاء الله لمنعهم من الشرك قهرًا، لكنّه ابتلاءٌ بحكمته؛ ولستَ يا محمد حفيظًا تحصي أعمالهم ولا موكّلًا بهدايتهم؛ إنّما أنت مبلّغ؛ فلا تحمل ما ليس عليك. فالهدايةُ بيد الله، والداعي مبلّغٌ لا محاسب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ بأنّ الهدايةَ بيد الله وطرحُ ما لا يُطاق."},"action":{"text":"بلّغ ولا تحمل همّ هداية الناس فوق طاقتك، فمشيئةُ الهداية لله."}},{"n":108,"reflection":{"text":"«ولا تسبوا الذين يدعون من دون الله فيسبوا الله عدوا بغير علم كذلك زينا لكل أمة عملهم ثم إلى ربهم مرجعهم فينبئهم بما كانوا يعملون» — لا تسبّوا آلهةَ المشركين فيسبّوا اللهَ ظلمًا وجهلًا مقابلةً لكم؛ فسدّ الله ذريعةَ الشرّ ولو كان في السبّ مصلحةٌ ظاهرة؛ ثمّ مرجعُ الجميع إليه فيجازيهم. قاعدةٌ عظيمة في سدّ الذرائع: يُترك الجائزُ إذا أفضى إلى محرّمٍ أعظم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"سدُّ الذرائعِ وتركُ ما يُفضي إلى شرٍّ أكبر."},"action":{"text":"لا تفعل مباحًا يجرّ إلى منكرٍ أعظم، فحفظُ حرمة الله أولى من التشفّي."}},{"n":109,"reflection":{"text":"«وأقسموا بالله جهد أيمانهم لئن جاءتهم آية ليؤمنن بها قل إنما الآيات عند الله وما يشعركم أنها إذا جاءت لا يؤمنون» — حلف المشركون مؤكّدين أنّهم لو جاءتهم آيةٌ حسّيّةٌ يقترحونها لآمنوا؛ قل: الآياتُ عند الله ينزّلها بحكمته لا باقتراحكم؛ وما يدريكم أنّها لو جاءت لا يؤمنون؟ فقد عاندوا آياتٍ كثيرة. فالمعاندُ لا تنفعه الآياتُ المقترحة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ العنادَ لا تشفيه الآياتُ المقترحة."},"action":{"text":"لا تعلّق إيمانك على آيةٍ تقترحها، فالمعاندُ لا يؤمن ولو رأى كلَّ آية."}},{"n":110,"reflection":{"text":"«ونقلب أفئدتهم وأبصارهم كما لم يؤمنوا به أول مرة ونذرهم في طغيانهم يعمهون» — ونصرف قلوبهم وأبصارهم عن الحقّ عقوبةً لهم كما أعرضوا عنه أوّلَ مرّةٍ باختيارهم؛ ونتركهم في ضلالهم يتحيّرون؛ فمن أعرض عن الهدى أوّلًا حُرمه جزاءً. فالإعراضُ الأوّلُ يجرّ عقوبةَ الحرمان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإعراضِ الأوّلِ الذي يجرّ الحرمان."},"action":{"text":"بادر بقبول الحقّ أوّلَ ما يتبيّن لك، فالإعراضُ عنه عقوبتُه تقليبُ القلب وحرمانُه."}}]}],"coverage":{"covered":110,"total":165}};
